//! Phonetic search pattern (iAvro `RegexParser`): a Latin term becomes a
//! regular expression over Bangla describing every spelling it can stand for,
//! using the `search.zon` grammar (iAvro `regex.json`, regenerated by
//! `zig build grammars`). `Matcher` compiles it to an NFA over code points and
//! matches whole words, iAvro anchoring it as `^…$`.
//!
//! `Matcher.collectSorted` walks a byte-sorted word list like a trie: words that
//! share a prefix reuse its state sets, and once a prefix can no longer match,
//! every word starting with it is skipped by binary search.

const std = @import("std");
const Grammar = @import("transliteration").Grammar;

pub const grammar: Grammar = @import("search.zon");

/// Appended after every pattern by iAvro's RegexParser: optional ্য/্ব/্ম phala,
/// hasanta, and ঃ/ঁ.
const pattern_tail = "(্[যবম])?(্?)([ঃঁ]?)";

const pattern_index = blk: {
    @setEvalBranchQuota(100_000);
    var kvs: [grammar.patterns.len]struct { []const u8, usize } = undefined;
    for (grammar.patterns, 0..) |p, i| kvs[i] = .{ p.find, i };
    break :blk std.StaticStringMap(usize).initComptime(kvs);
};

const max_pattern_len = blk: {
    var max: usize = 0;
    for (grammar.patterns) |p| max = @max(max, p.find.len);
    break :blk max;
};

fn inSet(comptime set: []const u8, c: u8) bool {
    return std.mem.indexOfScalar(u8, set, std.ascii.toLower(c)) != null;
}

fn isVowelAscii(c: u8) bool {
    return inSet(grammar.vowel, c);
}

fn isConsonantAscii(c: u8) bool {
    return inSet(grammar.consonant, c);
}

fn isPunctuationAscii(c: u8) bool {
    return !(isVowelAscii(c) or isConsonantAscii(c));
}

/// iAvro `RegexParser.parse`: the Bangla regular expression a Latin `term` can
/// stand for. `regex.json` marks its punctuation "case sensitive", and `clean`
/// drops those characters, so the result never contains regex syntax from the
/// input.
pub fn regexFor(allocator: std.mem.Allocator, term: []const u8) ![]u8 {
    var fixed: std.ArrayList(u8) = .empty;
    defer fixed.deinit(allocator);
    for (term) |c| {
        if (c < 0x80 and inSet(grammar.casesensitive, c)) continue;
        try fixed.append(allocator, if (c < 0x80) std.ascii.toLower(c) else c);
    }
    const s = fixed.items;

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    var cur: usize = 0;
    while (cur < s.len) : (cur += 1) {
        const start = cur;
        var matched = false;
        var chunk_len: usize = @min(max_pattern_len, s.len - start);
        while (chunk_len > 0 and !matched) : (chunk_len -= 1) {
            const end = start + chunk_len;
            const pattern = grammar.patterns[pattern_index.get(s[start..end]) orelse continue];
            const replace = for (pattern.rules orelse &.{}) |rule| {
                if (ruleApplies(rule, s, start, end)) break rule.replace;
            } else pattern.replace;
            try out.appendSlice(allocator, replace);
            try out.appendSlice(allocator, pattern_tail);
            cur = end - 1;
            matched = true;
        }
        if (!matched) {
            // No pattern: the character stands for itself (whole UTF-8 sequence).
            const n = std.unicode.utf8ByteSequenceLength(s[cur]) catch 1;
            try out.appendSlice(allocator, s[cur..@min(cur + n, s.len)]);
            cur += n - 1;
        }
    }
    return out.toOwnedSlice(allocator);
}

fn ruleApplies(rule: Grammar.Rule, s: []const u8, start: usize, end: usize) bool {
    const len: isize = @intCast(s.len);
    for (rule.matches) |m| {
        const chk: isize = if (m.type == .suffix) @intCast(end) else @as(isize, @intCast(start)) - 1;
        const in_range = (chk >= 0 and m.type == .prefix) or (chk < len and m.type == .suffix);
        const scope = m.scope orelse continue;
        const value = m.value orelse "";
        const ok = switch (scope) {
            .punctuation => (chk < 0 and m.type == .prefix) or (chk >= len and m.type == .suffix) or
                isPunctuationAscii(s[@intCast(chk)]),
            .vowel => in_range and isVowelAscii(s[@intCast(chk)]),
            .consonant => in_range and isConsonantAscii(s[@intCast(chk)]),
            .exact => blk: {
                const vlen: isize = @intCast(value.len);
                const b: isize = if (m.type == .suffix) @intCast(end) else @as(isize, @intCast(start)) - vlen;
                const e = b + vlen;
                // iAvro's isExact requires `end < length` (strictly), kept as is.
                const hit = b >= 0 and e < len and std.mem.eql(u8, s[@intCast(b)..@intCast(e)], value);
                break :blk hit;
            },
        };
        if (ok == m.negative) return false;
    }
    return true;
}

/// A `regexFor` expression compiled to a Thompson NFA over code points, matched
/// against whole words (iAvro anchors it as `^…$`). Handles the syntax
/// `regex.json` uses: literals, `[…]` sets, `( | )` groups and `?`.
pub const Matcher = struct {
    const Kind = enum(u8) { char, set, split, eps, match };
    const State = struct {
        kind: Kind,
        c: u21 = 0,
        /// `set`: range into `set_cps`.
        lo: u32 = 0,
        hi: u32 = 0,
        out: u32 = 0,
        out1: u32 = 0,
    };
    const Frag = struct { start: u32, end: u32 };
    const BitSet = std.DynamicBitSetUnmanaged;

    allocator: std.mem.Allocator,
    states: std.ArrayList(State) = .empty,
    set_cps: std.ArrayList(u21) = .empty,
    start: u32 = 0,
    accept: u32 = 0,
    /// Per-depth state sets for `collectSorted`; `sets[d]` is after `d` code points.
    sets: std.ArrayList(BitSet) = .empty,
    stack: std.ArrayList(u32) = .empty,

    pub fn init(allocator: std.mem.Allocator, regex: []const u8) !Matcher {
        var self: Matcher = .{ .allocator = allocator };
        errdefer self.deinit();
        var cps: std.ArrayList(u21) = .empty;
        defer cps.deinit(allocator);
        var it = (try std.unicode.Utf8View.init(regex)).iterator();
        while (it.nextCodepoint()) |cp| try cps.append(allocator, cp);

        var pos: usize = 0;
        const frag = try self.parseAlt(cps.items, &pos);
        if (pos != cps.items.len) return error.InvalidRegex;
        self.accept = try self.add(.{ .kind = .match });
        self.states.items[frag.end].out = self.accept;
        self.start = frag.start;
        return self;
    }

    pub fn deinit(self: *Matcher) void {
        for (self.sets.items) |*s| s.deinit(self.allocator);
        self.sets.deinit(self.allocator);
        self.stack.deinit(self.allocator);
        self.states.deinit(self.allocator);
        self.set_cps.deinit(self.allocator);
    }

    fn add(self: *Matcher, s: State) !u32 {
        try self.states.append(self.allocator, s);
        return @intCast(self.states.items.len - 1);
    }

    fn eps(self: *Matcher) !Frag {
        const e = try self.add(.{ .kind = .eps });
        return .{ .start = e, .end = e };
    }

    fn parseAlt(self: *Matcher, cps: []const u21, pos: *usize) anyerror!Frag {
        var frag = try self.parseConcat(cps, pos);
        while (pos.* < cps.len and cps[pos.*] == '|') {
            pos.* += 1;
            const rhs = try self.parseConcat(cps, pos);
            const end = try self.add(.{ .kind = .eps });
            const fork = try self.add(.{ .kind = .split, .out = frag.start, .out1 = rhs.start });
            self.states.items[frag.end].out = end;
            self.states.items[rhs.end].out = end;
            frag = .{ .start = fork, .end = end };
        }
        return frag;
    }

    fn parseConcat(self: *Matcher, cps: []const u21, pos: *usize) anyerror!Frag {
        var frag: ?Frag = null;
        while (pos.* < cps.len and cps[pos.*] != '|' and cps[pos.*] != ')') {
            var atom = try self.parseAtom(cps, pos);
            while (pos.* < cps.len and cps[pos.*] == '?') {
                pos.* += 1;
                const end = try self.add(.{ .kind = .eps });
                const fork = try self.add(.{ .kind = .split, .out = atom.start, .out1 = end });
                self.states.items[atom.end].out = end;
                atom = .{ .start = fork, .end = end };
            }
            if (frag) |f| {
                self.states.items[f.end].out = atom.start;
                frag = .{ .start = f.start, .end = atom.end };
            } else frag = atom;
        }
        return frag orelse try self.eps();
    }

    fn parseAtom(self: *Matcher, cps: []const u21, pos: *usize) anyerror!Frag {
        const c = cps[pos.*];
        pos.* += 1;
        switch (c) {
            '(' => {
                const inner = try self.parseAlt(cps, pos);
                if (pos.* >= cps.len or cps[pos.*] != ')') return error.InvalidRegex;
                pos.* += 1;
                return inner;
            },
            '[' => {
                const lo: u32 = @intCast(self.set_cps.items.len);
                while (pos.* < cps.len and cps[pos.*] != ']') : (pos.* += 1) {
                    try self.set_cps.append(self.allocator, cps[pos.*]);
                }
                if (pos.* >= cps.len) return error.InvalidRegex;
                pos.* += 1;
                const end = try self.add(.{ .kind = .eps });
                const s = try self.add(.{ .kind = .set, .lo = lo, .hi = @intCast(self.set_cps.items.len), .out = end });
                return .{ .start = s, .end = end };
            },
            else => {
                const end = try self.add(.{ .kind = .eps });
                const s = try self.add(.{ .kind = .char, .c = c, .out = end });
                return .{ .start = s, .end = end };
            },
        }
    }

    fn closure(self: *Matcher, set: *BitSet, from: u32) !void {
        self.stack.clearRetainingCapacity();
        try self.stack.append(self.allocator, from);
        while (self.stack.pop()) |s| {
            if (set.isSet(s)) continue;
            set.set(s);
            const st = self.states.items[s];
            switch (st.kind) {
                .split => {
                    try self.stack.append(self.allocator, st.out1);
                    try self.stack.append(self.allocator, st.out);
                },
                .eps => try self.stack.append(self.allocator, st.out),
                else => {},
            }
        }
    }

    /// `next` = states reachable from `cur` by consuming `cp`. False if none.
    fn step(self: *Matcher, cur: *const BitSet, cp: u21, next: *BitSet) !bool {
        next.unsetAll();
        var any = false;
        var it = cur.iterator(.{});
        while (it.next()) |i| {
            const st = self.states.items[i];
            const hit = switch (st.kind) {
                .char => st.c == cp,
                .set => std.mem.indexOfScalar(u21, self.set_cps.items[st.lo..st.hi], cp) != null,
                else => false,
            };
            if (hit) {
                try self.closure(next, st.out);
                any = true;
            }
        }
        return any;
    }

    fn depthSet(self: *Matcher, d: usize) !*BitSet {
        while (self.sets.items.len <= d) {
            try self.sets.append(self.allocator, try BitSet.initEmpty(self.allocator, self.states.items.len));
        }
        return &self.sets.items[d];
    }

    /// Whether the whole of `word` matches.
    pub fn matches(self: *Matcher, word: []const u8) !bool {
        const s0 = try self.depthSet(0);
        s0.unsetAll();
        try self.closure(s0, self.start);
        var d: usize = 0;
        var it = (std.unicode.Utf8View.init(word) catch return false).iterator();
        while (it.nextCodepoint()) |cp| : (d += 1) {
            // Grow first: depthSet may reallocate and move `sets`.
            const next = try self.depthSet(d + 1);
            const cur = &self.sets.items[d];
            if (!try self.step(cur, cp, next)) return false;
        }
        return (try self.depthSet(d)).isSet(self.accept);
    }

    /// Append to `out` every word of `words` (byte-sorted; `words.len()` and
    /// `words.get(i)`) that matches. Consecutive words reuse the state sets of
    /// their common prefix, and once a prefix is dead every word starting with
    /// it is skipped by binary search.
    pub fn collectSorted(self: *Matcher, words: anytype, out: *std.ArrayList([]const u8), out_allocator: std.mem.Allocator) !void {
        const n = words.len();
        if (n == 0) return;
        const s0 = try self.depthSet(0);
        s0.unsetAll();
        try self.closure(s0, self.start);

        var prev: []const u8 = "";
        var valid: usize = 0; // state sets 0..valid hold for prev's first `valid` code points
        var i: usize = 0;
        while (i < n) {
            const w = words.get(i);
            // Common whole-code-point prefix with prev, capped at the valid depth.
            var d: usize = 0;
            var at: usize = 0;
            while (d < valid and at < w.len and at < prev.len) {
                const len = std.unicode.utf8ByteSequenceLength(w[at]) catch 1;
                if (at + len > w.len or at + len > prev.len or !std.mem.eql(u8, w[at..][0..len], prev[at..][0..len])) break;
                at += len;
                d += 1;
            }
            prev = w;
            valid = d;

            var dead_at: ?usize = null;
            while (at < w.len) {
                const len = std.unicode.utf8ByteSequenceLength(w[at]) catch 1;
                const cp = std.unicode.utf8Decode(w[at..@min(at + len, w.len)]) catch break;
                const next = try self.depthSet(d + 1);
                const cur = &self.sets.items[d];
                at += len;
                if (!try self.step(cur, cp, next)) {
                    dead_at = at;
                    break;
                }
                d += 1;
                valid = d;
            }

            if (dead_at) |end| {
                // Every following word starting with w[0..end] is dead too.
                const prefix = w[0..end];
                var lo = i + 1;
                var hi = n;
                while (lo < hi) {
                    const mid = lo + (hi - lo) / 2;
                    if (std.mem.startsWith(u8, words.get(mid), prefix)) lo = mid + 1 else hi = mid;
                }
                i = lo;
                continue;
            }
            if (self.sets.items[d].isSet(self.accept)) try out.append(out_allocator, w);
            i += 1;
        }
    }
};

// ------------ TESTING ------------
const testing = std.testing;

test "regexFor follows iAvro RegexParser" {
    const a = testing.allocator;
    const r = try regexFor(a, "k");
    defer a.free(r);
    try testing.expectEqualStrings("ক" ++ pattern_tail, r);
    // regex.json's "case sensitive" punctuation is dropped.
    const r2 = try regexFor(a, "K.");
    defer a.free(r2);
    try testing.expectEqualStrings(r, r2);
}

test "Matcher matches whole words" {
    const a = testing.allocator;
    const re = try regexFor(a, "ami");
    defer a.free(re);
    var m = try Matcher.init(a, re);
    defer m.deinit();
    try testing.expect(try m.matches("আমি"));
    try testing.expect(try m.matches("আমী"));
    try testing.expect(!try m.matches("আমিন"));
    try testing.expect(!try m.matches("কমি"));
}

test "collectSorted equals matching each word" {
    const a = testing.allocator;
    const re = try regexFor(a, "ama");
    defer a.free(re);
    var m = try Matcher.init(a, re);
    defer m.deinit();
    const list = [_][]const u8{ "আম", "আমা", "আমার", "আমায়", "আমি", "এমা", "কমা" };
    const Words = struct {
        items: []const []const u8,
        pub fn len(w: @This()) usize {
            return w.items.len;
        }
        pub fn get(w: @This(), i: usize) []const u8 {
            return w.items[i];
        }
    };
    var got: std.ArrayList([]const u8) = .empty;
    defer got.deinit(a);
    try m.collectSorted(Words{ .items = &list }, &got, a);
    var want: std.ArrayList([]const u8) = .empty;
    defer want.deinit(a);
    for (list) |w| if (try m.matches(w)) try want.append(a, w);
    try testing.expectEqual(want.items.len, got.items.len);
    for (want.items, got.items) |x, y| try testing.expectEqualStrings(x, y);
    try testing.expect(want.items.len >= 2);
}

